'use strict';

// MODULES //

var getDType = require( '@stdlib/ndarray/base/dtype' );
var getShape = require( '@stdlib/ndarray/base/shape' );
var getStrides = require( '@stdlib/ndarray/base/strides' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getOrder = require( '@stdlib/ndarray/base/order' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var toUniqueNormalizedIndices = require( '@stdlib/ndarray/base/to-unique-normalized-indices' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns a view of an input ndarray in which two specified dimensions are swapped.
*
* @param {ndarray} x - input array
* @param {IntegerArray} dims - indices of dimensions to swap
* @param {boolean} writable - boolean indicating whether a returned ndarray should be writable
* @throws {TypeError} first argument must be an ndarray having two or more dimensions
* @throws {RangeError} specified dimension index is out-of-bounds
* @throws {Error} must provide two unique dimension indices
* @returns {ndarray} ndarray view
*
* @example
* var array = require( '@stdlib/ndarray/array' );
*
* var x = array( [ [ [ 1, 2 ], [ 3, 4 ] ], [ [ 5, 6 ], [ 7, 8 ] ] ] );
* // returns <ndarray>[ [ [ 1, 2 ], [ 3, 4 ] ], [ [ 5, 6 ], [ 7, 8 ] ] ]
*
* var y = swapDimensions( x, [ 0, 1 ], false );
* // returns <ndarray>[ [ [ 1, 2 ], [ 5, 6 ] ], [ [ 3, 4 ], [ 7, 8 ] ] ]
*/
function swapDimensions( x, dims, writable ) {
	var tmp;
	var sh;
	var st;
	var d1;
	var d2;
	var d;
	var N;

	sh = getShape( x, true );
	N = sh.length;
	if ( N < 2 ) {
		throw new TypeError( format( 'invalid argument. First argument must be an ndarray having two or more dimensions. Number of dimensions: %d.', N ) );
	}

	// Normalize dimension indices:
	d = toUniqueNormalizedIndices( dims, N-1 );
	if ( d === null ) {
		throw new RangeError( format( 'invalid argument. Specified dimension index is out-of-bounds. Must be on the interval: [-%u, %u]. Value: `[%s]`.', N, N-1, join( dims, ', ' ) ) );
	}
	if ( d.length !== dims.length || d.length !== 2 ) {
		throw new Error( format( 'invalid argument. Must provide two unique dimension indices. Value: `[%s]`.', join( dims, ', ' ) ) );
	}
	st = getStrides( x, true );
	d1 = d[ 0 ];
	d2 = d[ 1 ];

	// Swap shapes:
	tmp = sh[ d1 ];
	sh[ d1 ] = sh[ d2 ];
	sh[ d2 ] = tmp;

	// Swap strides:
	tmp = st[ d1 ];
	st[ d1 ] = st[ d2 ];
	st[ d2 ] = tmp;

	return new x.constructor( getDType( x ), getData( x ), sh, st, getOffset( x ), getOrder( x ), { // eslint-disable-line max-len
		'readonly': !writable
	});
}


// EXPORTS //

module.exports = swapDimensions;
